import {parseCSV,DIRECTIONS,HEADS,LABELS} from './validation.js';import {csv} from './engine.js';
const $=id=>document.getElementById(id);let data=[],timing=false,page=0,videoURL=null,dirty=false,headers=[];
function feedback(t){$('feedback').textContent=t;}
$('videoFile').onchange=()=>{let f=$('videoFile').files[0];if(!f)return;if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(f);$('referenceVideo').src=videoURL;};
$('templateFile').onchange=async()=>{try{const file=$('templateFile').files[0];if(!file)return;const rows=parseCSV(await file.text());if(!rows.length)throw Error('구간/사건이 없는 양식입니다.');const nextTiming='kind' in rows[0];const required=nextTiming?['session_id','id','kind','start_s','end_s']:['session_id','bin_start_s','bin_end_s','direction','screen','head'];if(!required.every(k=>k in rows[0]))throw Error('필수 열이 없습니다. 빈 A 양식 또는 작성한 A CSV를 사용하세요.');if(rows.some(r=>r.session_id!==rows[0].session_id))throw Error('한 세션의 양식만 불러올 수 있습니다.');if(rows.some(r=>'gaze_failure_fraction' in r||'direction_failure_fraction' in r))throw Error('프로그램 예측 CSV입니다. A 평가 양식을 사용하세요.');
if(!nextTiming)for(const r of rows)for(const f of ['direction','screen','head'])if(r[f]&&!((f==='direction'?DIRECTIONS:f==='head'?HEADS:['INSIDE','OUTSIDE']).includes(r[f])||r[f]==='UNCLEAR'))throw Error('알 수 없는 상태 코드가 있습니다.');
const codes=[...new Set(rows.map(r=>r.rater_id).filter(Boolean))];if(codes.length>1)throw Error('평가자 코드가 혼재되어 있습니다.');if(codes.length)$('raterId').value=codes[0];timing=nextTiming;data=rows;headers=[...new Set([...Object.keys(rows[0]),'rater_id','video_offset_s',...(timing?['time_basis']:[])])];if(rows[0].video_offset_s!==undefined&&rows[0].video_offset_s!=='')$('offset').value=rows[0].video_offset_s;$('timeBasis').value=rows[0].time_basis||'session';page=0;dirty=false;$('export').disabled=false;$('addEvent').disabled=!timing;render();feedback(data.length+'개 구간/사건 · 세션 '+rows[0].session_id);}catch(e){feedback(e.message);}finally{$('templateFile').value='';}};
function render(){const begin=page*20;$('heads').replaceChildren();const header=document.createElement('tr');for(const s of timing?['사건 ID','종류','시간축','시작 (초)','종료 (초)','구간 길이 (초)']:['구간 · 세션 초','영상 이동','시선 방향','화면 상태','머리 방향']){const th=document.createElement('th');th.textContent=s;header.append(th);}$('heads').append(header);$('rows').replaceChildren();for(const r of data.slice(begin,begin+20)){const tr=document.createElement('tr');const add=v=>{const td=document.createElement('td');if(v instanceof Node)td.append(v);else td.textContent=v;tr.append(td);};if(timing){add(r.id);const kind=document.createElement('select');for(const [k,v]of Object.entries({GAZE:'주시 지속시간',RESPONSE:'반응시간',DELAY:'지연시간'}))kind.add(new Option(v,k));kind.value=r.kind;kind.onchange=()=>{r.kind=kind.value;dirty=true;};add(kind);const basis=document.createElement('select');basis.add(new Option('세션','session'));basis.add(new Option('영상','video'));basis.value=r.time_basis||'session';basis.onchange=()=>{r.time_basis=basis.value;dirty=true;};add(basis);let duration=document.createElement('span');const update=()=>duration.textContent=r.start_s!==''&&r.end_s!==''?Number(r.end_s)-Number(r.start_s):'미입력';for(const f of ['start_s','end_s']){let input=document.createElement('input');input.type='number';input.min=0;input.step=.001;input.value=r[f];input.oninput=()=>{r[f]=input.value;dirty=true;update();};add(input);}update();add(duration);}else{add(r.bin_start_s+' – '+r.bin_end_s);const seek=document.createElement('button');seek.textContent='구간 보기';seek.onclick=()=>{const v=$('referenceVideo');v.pause();v.currentTime=Math.max(0,Number(r.bin_start_s)-Number($('offset').value));};add(seek);for(const f of ['direction','screen','head']){const select=document.createElement('select');select.add(new Option('미입력',''));const labels=f==='direction'?DIRECTIONS:f==='head'?HEADS:['INSIDE','OUTSIDE'];for(const k of [...labels,'UNCLEAR'])select.add(new Option(LABELS[k],k));select.value=r[f];select.onchange=()=>{r[f]=select.value;dirty=true;};add(select);}}$('rows').append(tr);}$('pageCount').textContent=(page+1)+' / '+Math.ceil(data.length/20);$('prevPage').disabled=page===0;$('nextPage').disabled=begin+20>=data.length;}
$('prevPage').onclick=()=>{page--;render();};$('nextPage').onclick=()=>{page++;render();};
$('addEvent').onclick=()=>{if(!timing||!data.length)return;let n=1;while(data.some(r=>r.id==='A'+n))n++;data.push({...Object.fromEntries(headers.map(h=>[h,data[0][h]??''])),id:'A'+n,kind:'GAZE',start_s:'',end_s:'',time_basis:$('timeBasis').value});page=Math.floor((data.length-1)/20);dirty=true;render();};
$('offset').onchange=$('raterId').oninput=()=>{if(data.length)dirty=true;};
for(const [id,sign] of [['prevFrame',-1],['nextFrame',1]])$(id).onclick=()=>{const v=$('referenceVideo');v.pause();v.currentTime=Math.max(0,v.currentTime+sign/Math.max(1,Number($('videoFps').value)));};
$('export').onclick=()=>{if(!data.length)return;const code=$('raterId').value.trim(),offset=Number($('offset').value);if(!code||!Number.isFinite(offset)||offset<0){feedback('평가자 코드와 유효한 영상 시작 시각을 입력하세요.');return;}if(timing&&data.some(r=>(r.start_s===''&&r.end_s!=='')||(r.start_s!==''&&r.end_s==='')||(r.start_s!==''&&(Number(r.start_s)<0||Number(r.end_s)<Number(r.start_s))))){feedback('시간은 시작·종료를 모두 입력하거나 모두 비워 주세요. 종료는 시작보다 빠를 수 없습니다.');return;}const incomplete=data.filter(r=>timing?r.start_s===''||r.end_s==='':!r.direction||!r.screen||!r.head).length;const exported=data.map(r=>{const shift=r.time_basis==='video'?offset:0,start=r.start_s===''?null:Number(r.start_s)+shift,end=r.end_s===''?null:Number(r.end_s)+shift;return {...r,rater_id:code,video_offset_s:offset,...(timing?{time_basis:r.time_basis||'session',session_start_s:start,session_end_s:end,duration_s:start!==null&&end!==null?end-start:null}:{})};});let url=URL.createObjectURL(new Blob([csv([headers,...exported.map(r=>headers.map(h=>r[h]??''))])],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(data[0].session_id+'_'+code+(timing?'_timing':'_observations')+'.csv').replace(/[^a-zA-Z0-9_.-]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);dirty=false;feedback('다운로드했습니다. 미완료 '+incomplete+'개 · 빈칸은 미입력으로 집계됩니다.');};
addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
